{"content": "from datetime import date, timedelta
from typing import Any, Optional

from pydantic import BaseModel, model_validator


class Booking(BaseModel):
    start: date
    end: date
    nights: Optional[int] = None

    @model_validator(mode="before")
    @classmethod
    def default_end(cls, data: Any) -> Any:
        if isinstance(data, dict) and "end" not in data and "start" in data and "nights" in data:
            start = date.fromisoformat(str(data["start"]))
            data = dict(data, end=start + timedelta(days=int(data["nights"])))
        return data

    @model_validator(mode="after")
    def check_order(self) -> "Booking":
        if self.end <= self.start:
            raise ValueError("end must be after start")
        self.nights = (self.end - self.start).days
        return self
